**Add** the parts when the solid is built up, such as a cone sitting on a cylinder.

[tikz]% mathsmap-solid {"version":1,"kind":"analytic-cone","radius":1.2,"projectedRadius":0.4,"height":1.7999999999999998}

\begin{tikzpicture}[every node/.style={font=\large}]
\draw (-1.2,0) -- (-1.2,2.2);
\draw (1.2,0) -- (1.2,2.2);
\draw (-1.2,0) arc[start angle=180, end angle=360, x radius=1.2, y radius=0.4];
\draw[dashed] (-1.2,0) arc[start angle=180, end angle=0, x radius=1.2, y radius=0.4];
\draw (-1.16999525,2.28888889) arc (167.16041159:372.83958841:1.2 and 0.4);
\draw[dashed] (1.16999525,2.28888889) arc (12.83958841:167.16041159:1.2 and 0.4);
\coordinate (T) at (0,4.0);
\draw (T)--(-1.16999525,2.28888889);
\draw (T)--(1.16999525,2.28888889);
